import { Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { AuthService } from '../../../core/services/auth.service';
import { SupabaseService } from '../../../core/services/supabase.service';

/**
 * Password reset. The e-mail link is generated by Supabase Auth; this
 * application never sees or stores the password.
 */
@Component({
  selector: 'app-forgot-password',
  imports: [FormsModule, RouterLink],
  templateUrl: './forgot-password.html',
})
export class ForgotPasswordComponent {
  private readonly auth = inject(AuthService);
  readonly supabase = inject(SupabaseService);

  readonly email = signal('');
  readonly busy = signal(false);
  readonly sent = signal(false);
  readonly error = signal<string | null>(null);

  async submit(): Promise<void> {
    this.error.set(null);
    if (!this.email().trim()) {
      this.error.set('Please enter your college e-mail address.');
      return;
    }

    this.busy.set(true);
    try {
      await this.auth.sendPasswordReset(this.email().trim());
      this.sent.set(true);
    } catch (caught) {
      this.error.set(caught instanceof Error ? caught.message : 'Could not send the reset e-mail.');
    } finally {
      this.busy.set(false);
    }
  }
}
